<title>UNIFCO | Client Dashboard</title>
<style>
:root{font-family:Inter,Arial,sans-serif;--navy:#06275c;--navy2:#071f4d;--red:#e20b24;--blue:#1475d1;--green:#16945f;--amber:#f4a51c;--bg:#f6f8fb;--line:#e1e6ee;--muted:#6d7b90}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--navy2)}a{text-decoration:none;color:inherit}.app{min-height:100vh;display:grid;grid-template-columns:222px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100vh;background:linear-gradient(180deg,#06275c,#042252);color:#fff;padding:20px 12px;display:flex;flex-direction:column;z-index:20}.side-logo{width:155px;height:76px;object-fit:contain;align-self:center;margin-bottom:14px}.nav{display:grid;gap:5px}.nav a{display:flex;gap:11px;align-items:center;padding:11px 13px;border-radius:8px;font-size:13px;color:#fff}.nav a.active,.nav a:hover{background:rgba(255,255,255,.12)}.nav .ico{width:21px;text-align:center}.logout{margin-top:auto}.logout button{width:100%;border:1px solid rgba(255,255,255,.2);background:transparent;color:#fff;padding:10px;border-radius:8px;cursor:pointer}.main{min-width:0;padding:0 22px 42px}.topbar{height:72px;display:flex;align-items:center;gap:18px;border-bottom:1px solid var(--line);background:#fff;margin:0 -22px;padding:0 24px;position:sticky;top:0;z-index:15}.welcome{flex:1}.welcome h1{font-size:18px;margin:0 0 5px}.welcome p{font-size:12px;color:var(--muted);margin:0}.top-actions{display:flex;align-items:center;gap:18px;font-size:12px}.avatar{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;background:var(--navy);color:#fff;font-weight:800}.content{padding-top:24px;max-width:1380px;margin:auto}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:11px;box-shadow:0 3px 12px rgba(9,39,82,.035)}.stat{padding:18px}.stat .label{font-size:11px;font-weight:700}.stat .value{font-size:28px;font-weight:850;margin:16px 0 8px}.trend{font-size:11px;color:var(--green)}.trend.red{color:var(--red)}.dashboard-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.panel{padding:17px}.panel h2{font-size:14px;margin:0 0 16px}.work-overview{display:grid;grid-template-columns:190px 1fr;align-items:center;gap:22px}.donut{width:130px;height:130px;border-radius:50%;margin:auto;background:conic-gradient(var(--blue) 0 var(--p1),var(--amber) var(--p1) var(--p2),var(--green) var(--p2) var(--p3),var(--red) var(--p3) 100%);position:relative}.donut:after{content:"";position:absolute;inset:23px;border-radius:50%;background:#fff}.donut-center{position:absolute;inset:0;display:grid;place-items:center;z-index:2;text-align:center;font-size:11px}.donut-center strong{font-size:22px;display:block}.legend{display:grid;gap:11px;font-size:11px}.legend-row{display:grid;grid-template-columns:10px 1fr auto;gap:8px;align-items:center}.dot{width:8px;height:8px;border-radius:50%}.recent{display:grid;gap:10px}.wo-row{display:grid;grid-template-columns:32px 1fr auto;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid #eef1f5}.wo-row:last-child{border-bottom:0}.wo-icon{width:30px;height:30px;border-radius:6px;background:#edf4fd;display:grid;place-items:center;color:var(--blue)}.wo-title{font-size:11px;font-weight:800}.wo-sub{font-size:10px;color:var(--muted);margin-top:3px}.pill{display:inline-flex;padding:4px 8px;border-radius:6px;font-size:9px;background:#edf4fd;color:#3268a5}.pill.green{background:#e7f7ee;color:#137346}.pill.amber{background:#fff4df;color:#a96b04}.pill.red{background:#fdebed;color:#b42239}.lower-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.sla-wrap{height:140px;display:grid;place-items:center}.gauge{width:190px;height:95px;overflow:hidden;position:relative}.gauge:before{content:"";position:absolute;width:190px;height:190px;border-radius:50%;border:18px solid #e6edf3;border-bottom-color:transparent;border-left-color:var(--green);border-top-color:var(--green);border-right-color:var(--green);transform:rotate(45deg);top:10px;left:0}.gauge-value{position:absolute;left:0;right:0;bottom:0;text-align:center}.gauge-value strong{font-size:25px;display:block}.upcoming{display:grid;gap:11px}.plan{display:grid;grid-template-columns:34px 1fr auto;gap:10px;align-items:center}.cal{width:30px;height:30px;border-radius:6px;background:#fff4df;color:#c47a00;display:grid;place-items:center}.workspace{margin-top:28px}.workspace-title{display:flex;justify-content:space-between;gap:12px;align-items:end;margin-bottom:12px}.workspace-title h2{margin:0;font-size:20px}.workspace-title p{margin:4px 0 0;color:var(--muted);font-size:12px}.section{margin-top:14px;padding:18px}.section h3{font-size:14px;margin:0 0 14px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:11px}.table th,.table td{padding:10px 8px;text-align:left;border-bottom:1px solid #edf0f4;white-space:nowrap}.table th{color:#68758a;font-size:10px;text-transform:uppercase}.asset-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.asset{padding:13px;border:1px solid #e4e9f0;border-radius:8px}.asset strong{font-size:12px}.asset small{display:block;margin-top:6px;line-height:1.55;color:var(--muted)}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.field{display:grid;gap:6px;font-size:11px;font-weight:700}.field input,.field select,.field textarea{width:100%;border:1px solid #d6dee8;border-radius:7px;padding:9px;font:inherit;background:#fff}.field textarea{min-height:80px}.wide{grid-column:1/-1}.btn{border:0;border-radius:7px;background:var(--navy);color:#fff;padding:10px 15px;font-weight:750;cursor:pointer}.btn.red{background:var(--red)}.notice{padding:11px 13px;background:#e9f7ef;color:#176940;border-radius:8px;margin-bottom:12px;font-size:12px}.alert-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.alert{border:1px solid #e4e9f0;border-radius:8px;padding:12px}.alert strong{display:block;font-size:11px;margin-top:8px}.alert small{color:var(--muted)}@media(max-width:1050px){.app{grid-template-columns:82px 1fr}.side-logo{width:62px}.nav a{justify-content:center;padding:12px}.nav a span:not(.ico){display:none}.stats{grid-template-columns:repeat(2,1fr)}.asset-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.app{display:block}.sidebar{height:auto;position:sticky;padding:8px;flex-direction:row;overflow:auto;align-items:center}.side-logo{width:80px;height:44px;margin:0 8px 0 0}.nav{display:flex}.nav a{white-space:nowrap}.logout{display:none}.main{padding:0 12px 30px}.topbar{margin:0 -12px;padding:0 14px}.stats,.dashboard-grid,.lower-grid{grid-template-columns:1fr}.work-overview{grid-template-columns:1fr}.form-grid,.asset-grid,.alert-grid{grid-template-columns:1fr}.top-actions span:nth-child(-n+2){display:none}}
</style>
</head>
